<?php
declare(strict_types=1);
require __DIR__.'/../app/bootstrap.php';require __DIR__.'/../app/admin_shell.php';security_headers();require_admin();
$db=database();$state=admin_activity_resolution($db);$activity=$state['activity'];if(!$activity){header('Location: /admin/activities.php');exit;}$activityId=(int)$activity['id'];
student_account_reconcile_confirmed_registrations($db,$activityId);$default=course_default_cohort($db,$activityId,true);

if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){
    if(!verify_csrf('student-area',$_POST['_csrf']??null)){http_response_code(403);exit('Invalid request');}
    $action=(string)($_POST['action']??'');$returnPage=(int)($_POST['page_id']??0);
    try{
        if($action==='create_cohort')course_create_cohort($db,$activityId,(string)($_POST['title']??''),(string)($_POST['slug']??''),!empty($_POST['make_default']));
        elseif($action==='set_default_cohort')course_set_default_cohort($db,$activityId,(int)($_POST['cohort_id']??0));
        elseif($action==='set_cohort_status')course_set_cohort_status($db,$activityId,(int)($_POST['cohort_id']??0),(string)($_POST['status']??'active'));
        elseif($action==='add_lesson')course_add_lesson($db,$activityId,(string)($_POST['title']??''),(string)($_POST['lesson_key']??''));
        elseif($action==='set_release')course_set_lesson_release($db,(int)($_POST['cohort_id']??0),(int)($_POST['lesson_id']??0),!empty($_POST['released']));
        elseif($action==='set_page_access')student_page_set_access($db,$activityId,(int)($_POST['page_id']??0),(string)($_POST['access_level']??'public'));
        elseif($action==='save_section_map'){
            $pageId=(int)($_POST['page_id']??0);$page=cms_page_by_id($db,$pageId);if(!$page||(int)$page['activity_id']!==$activityId)throw new RuntimeException('Página inválida.');$doc=cms_page_doc($page,false);$sections=student_page_sections_from_document($doc);$mapping=is_array($_POST['lesson']??null)?$_POST['lesson']:[];foreach($sections as $key=>$label){$lessonId=(int)($mapping[$key]??0);student_page_set_section_lesson($db,$pageId,$key,$lessonId>0?$lessonId:null);}
        }elseif($action==='assign_submission_cohort')student_account_assign_submission_cohort($db,(int)($_POST['submission_id']??0),$activityId,(int)($_POST['cohort_id']??0));
        elseif($action==='upload_private_media'){
            $pageId=(int)($_POST['page_id']??0);$file=$_FILES['media_file']??null;if(!is_array($file))throw new RuntimeException('Selecione uma imagem.');student_private_media_create($db,$activityId,$pageId,(string)($_POST['media_title']??''),$file);
        }elseif($action==='reconcile')student_account_reconcile_confirmed_registrations($db,$activityId);
        else throw new RuntimeException('Ação inválida.');
        $_SESSION['admin_notice']='Alteração salva.';
    }catch(Throwable $e){$_SESSION['admin_notice']='Não foi possível concluir: '.$e->getMessage();}
    $url='/admin/student-area.php?activity='.$activityId.($returnPage>0?'&page='.$returnPage:'');header('Location: '.$url,true,303);exit;
}

$cohorts=course_cohorts($db,$activityId);$lessons=course_lessons($db,$activityId);$notice=$_SESSION['admin_notice']??null;unset($_SESSION['admin_notice']);
$studentsQ=$db->prepare("SELECT u.id,u.name,u.email,u.activated_at,u.last_login_at,p.cpf_last4,e.status enrollment_status,e.confirmed_at,c.title cohort_title,c.id cohort_id FROM course_enrollments e JOIN student_users u ON u.id=e.student_id LEFT JOIN student_profiles p ON p.student_id=u.id JOIN course_cohorts c ON c.id=e.cohort_id WHERE c.activity_id=? ORDER BY c.id DESC,u.name COLLATE NOCASE");$studentsQ->execute([$activityId]);$students=$studentsQ->fetchAll();
$submissions=student_account_confirmed_submissions($db,$activityId);
$pagesQ=$db->prepare("SELECT * FROM cms_pages WHERE activity_id=? AND status!='archived' ORDER BY locale,sort_order,id");$pagesQ->execute([$activityId]);$pages=$pagesQ->fetchAll();
$selectedPageId=(int)($_GET['page']??0);if(!$selectedPageId)foreach($pages as $p)if(student_page_is_protected($p)){$selectedPageId=(int)$p['id'];break;}$selectedPage=$selectedPageId?cms_page_by_id($db,$selectedPageId):null;if($selectedPage&&(int)$selectedPage['activity_id']!==$activityId)$selectedPage=null;
$sections=$selectedPage?student_page_sections_from_document(cms_page_doc($selectedPage,false)):[];$sectionMap=$selectedPage?student_page_section_map($db,(int)$selectedPage['id']):[];$privateMedia=$selectedPage?student_private_media_for_page($db,(int)$selectedPage['id']):[];
admin_shell_start('students','Área do aluno',$state);?>
<?php if($notice):?><div class="admin-notice"><?=h((string)$notice)?></div><?php endif;?>
<section class="overview-hero"><div><h2>Área do aluno</h2><p>Uma matrícula confirmada cria o vínculo do aluno automaticamente. As páginas protegidas continuam sendo páginas normais do CMS; a liberação é feita por turma e por aula.</p></div><form method="post"><input type="hidden" name="_csrf" value="<?=h(csrf_token('student-area'))?>"><input type="hidden" name="action" value="reconcile"><button class="admin-button secondary" type="submit">Sincronizar inscrições confirmadas</button></form></section>

<section class="admin-card" style="margin-top:24px"><h2>Turmas</h2><p>A turma padrão recebe automaticamente novas matrículas confirmadas que ainda não tenham uma turma atribuída.</p><div class="admin-list" style="margin-top:16px"><?php foreach($cohorts as $cohort):?><article class="admin-list-row"><div class="admin-list-title"><strong><?=h((string)$cohort['title'])?></strong><span><?=h((string)$cohort['slug'])?><?=$cohort['is_registration_default']?' · padrão para novas confirmações':''?></span></div><div class="admin-list-meta"><?=h((string)$cohort['status'])?></div><div class="admin-list-actions"><?php if(!$cohort['is_registration_default']):?><form method="post"><input type="hidden" name="_csrf" value="<?=h(csrf_token('student-area'))?>"><input type="hidden" name="action" value="set_default_cohort"><input type="hidden" name="cohort_id" value="<?=(int)$cohort['id']?>"><button type="submit">Tornar padrão</button></form><?php endif;?><form method="post"><input type="hidden" name="_csrf" value="<?=h(csrf_token('student-area'))?>"><input type="hidden" name="action" value="set_cohort_status"><input type="hidden" name="cohort_id" value="<?=(int)$cohort['id']?>"><input type="hidden" name="status" value="<?=$cohort['status']==='active'?'closed':'active'?>"><button type="submit"><?=$cohort['status']==='active'?'Encerrar':'Reabrir'?></button></form></div></article><?php endforeach;?></div>
<form method="post" style="display:grid;grid-template-columns:2fr 1fr auto auto;gap:12px;margin-top:20px;align-items:end"><input type="hidden" name="_csrf" value="<?=h(csrf_token('student-area'))?>"><input type="hidden" name="action" value="create_cohort"><label>Nova turma<input name="title" required></label><label>Slug<input name="slug" placeholder="outubro-2026"></label><label style="display:flex;gap:8px;align-items:center"><input type="checkbox" name="make_default" value="1"> padrão</label><button class="admin-button" type="submit">Criar turma</button></form></section>

<section class="admin-card" style="margin-top:24px"><h2>Aulas e liberação</h2><p>Uma seção associada a uma aula só é enviada ao navegador quando aquela aula estiver liberada para a turma.</p><?php foreach($cohorts as $cohort):$releaseRows=course_lesson_release_rows($db,(int)$cohort['id'],$activityId);?><div style="margin-top:20px"><h3><?=h((string)$cohort['title'])?></h3><div class="admin-list"><?php foreach($releaseRows as $lesson):?><article class="admin-list-row"><div class="admin-list-title"><strong><?=h((string)$lesson['title'])?></strong><span><?=h((string)$lesson['lesson_key'])?></span></div><div class="admin-list-meta"><?=$lesson['released_at']?'Liberada em '.h((string)$lesson['released_at']):'Bloqueada'?></div><div class="admin-list-actions"><form method="post"><input type="hidden" name="_csrf" value="<?=h(csrf_token('student-area'))?>"><input type="hidden" name="action" value="set_release"><input type="hidden" name="cohort_id" value="<?=(int)$cohort['id']?>"><input type="hidden" name="lesson_id" value="<?=(int)$lesson['id']?>"><input type="hidden" name="released" value="<?=$lesson['released_at']?'0':'1'?>"><button type="submit"><?=$lesson['released_at']?'Bloquear':'Liberar'?></button></form></div></article><?php endforeach;?></div></div><?php endforeach;?>
<form method="post" style="display:grid;grid-template-columns:2fr 1fr auto;gap:12px;margin-top:20px;align-items:end"><input type="hidden" name="_csrf" value="<?=h(csrf_token('student-area'))?>"><input type="hidden" name="action" value="add_lesson"><label>Nova aula<input name="title" required></label><label>Identificador<input name="lesson_key" placeholder="aula-4"></label><button class="admin-button" type="submit">Adicionar aula</button></form></section>

<section class="admin-card" style="margin-top:24px"><h2>Páginas protegidas</h2><p>O conteúdo protegido usa <code>cms_pages</code>, igual às demais páginas do site. Não há importação de HTML em um sistema paralelo.</p><div class="admin-list" style="margin-top:16px"><?php foreach($pages as $page):?><article class="admin-list-row"><div class="admin-list-title"><strong><?=h((string)$page['title'])?></strong><span><?=h((string)$page['slug'])?> · <?=h(public_language_label((string)$page['locale']))?></span></div><div class="admin-list-meta"><?=student_page_is_protected($page)?'Somente matriculados':'Pública'?></div><div class="admin-list-actions"><a href="/admin/student-area.php?activity=<?=$activityId?>&page=<?=(int)$page['id']?>">Configurar</a><form method="post"><input type="hidden" name="_csrf" value="<?=h(csrf_token('student-area'))?>"><input type="hidden" name="action" value="set_page_access"><input type="hidden" name="page_id" value="<?=(int)$page['id']?>"><input type="hidden" name="access_level" value="<?=student_page_is_protected($page)?'public':'enrolled'?>"><button type="submit"><?=student_page_is_protected($page)?'Tornar pública':'Proteger'?></button></form></div></article><?php endforeach;?></div></section>

<?php if($selectedPage):?><section class="admin-card" style="margin-top:24px"><h2>Segmentação · <?=h((string)$selectedPage['title'])?></h2><p>Associe cada seção existente da página a uma aula. Se deixar “Sempre visível”, a seção aparece para qualquer matriculado com acesso à página.</p><?php if(!$sections):?><p>Nenhuma seção com identidade do CMS foi encontrada no rascunho atual.</p><?php else:?><form method="post" style="margin-top:16px"><input type="hidden" name="_csrf" value="<?=h(csrf_token('student-area'))?>"><input type="hidden" name="action" value="save_section_map"><input type="hidden" name="page_id" value="<?=(int)$selectedPage['id']?>"><div class="admin-list"><?php foreach($sections as $key=>$label):?><article class="admin-list-row"><div class="admin-list-title"><strong><?=h($label)?></strong><span><?=h($key)?></span></div><div class="admin-list-meta"><select name="lesson[<?=h($key)?>]"><option value="0">Sempre visível</option><?php foreach($lessons as $lesson):?><option value="<?=(int)$lesson['id']?>"<?=isset($sectionMap[$key])&&(int)$sectionMap[$key]['lesson_id']===(int)$lesson['id']?' selected':''?>><?=h((string)$lesson['title'])?></option><?php endforeach;?></select></div></article><?php endforeach;?></div><button class="admin-button" type="submit" style="margin-top:16px">Salvar segmentação</button></form><?php endif;?></section>
<section class="admin-card" style="margin-top:24px"><h2>Imagens privadas · <?=h((string)$selectedPage['title'])?></h2><p>Arquivos enviados aqui ficam em <code>storage/</code>, fora do acesso HTTP direto. A página recebe uma URL assinada, temporária e vinculada ao aluno. Use a referência abaixo como <code>src</code> no conteúdo da página.</p><form method="post" enctype="multipart/form-data" style="display:grid;grid-template-columns:1fr 1fr auto;gap:12px;align-items:end;margin-top:16px"><input type="hidden" name="_csrf" value="<?=h(csrf_token('student-area'))?>"><input type="hidden" name="action" value="upload_private_media"><input type="hidden" name="page_id" value="<?=(int)$selectedPage['id']?>"><label>Título<input name="media_title"></label><label>Imagem<input type="file" name="media_file" accept="image/jpeg,image/png,image/webp" required></label><button class="admin-button" type="submit">Enviar</button></form><?php if($privateMedia):?><div class="admin-list" style="margin-top:18px"><?php foreach($privateMedia as $media):?><article class="admin-list-row"><div class="admin-list-title"><strong><?=h((string)$media['title'])?></strong><span><?=h((string)$media['original_name'])?></span></div><div class="admin-list-meta"><code><?=h(student_private_media_placeholder($media))?></code></div></article><?php endforeach;?></div><?php endif;?></section><?php endif;?>

<section class="admin-card" style="margin-top:24px"><h2>Alunos</h2><p>Não existe cadastro manual: a conta nasce da inscrição confirmada.</p><?php if(!$students):?><p>Nenhuma matrícula confirmada.</p><?php else:?><div class="admin-list" style="margin-top:16px"><?php foreach($students as $student):?><article class="admin-list-row"><div class="admin-list-title"><strong><?=h((string)$student['name'])?></strong><span><?=h((string)$student['email'])?><?=$student['cpf_last4']?' · CPF final '.h((string)$student['cpf_last4']):''?></span></div><div class="admin-list-meta"><?=h((string)$student['cohort_title'])?> · <?=h((string)$student['enrollment_status'])?></div><div class="admin-list-meta"><?=$student['activated_at']?'Conta ativada':'Primeiro acesso pendente'?></div></article><?php endforeach;?></div><?php endif;?></section>

<section class="admin-card" style="margin-top:24px"><h2>Inscrições confirmadas e turma</h2><p>É possível mover uma inscrição confirmada para outra turma sem recriar a conta do aluno.</p><?php if(!$submissions):?><p>Nenhuma inscrição confirmada.</p><?php else:?><div class="admin-list" style="margin-top:16px"><?php foreach($submissions as $submission):$payload=json_decode((string)$submission['payload_json'],true)?:[];?><article class="admin-list-row"><div class="admin-list-title"><strong><?=h((string)($payload['name']??$payload['email']??'Inscrição'))?></strong><span><?=h((string)($payload['email']??''))?></span></div><div class="admin-list-meta"><form method="post" style="display:flex;gap:8px;align-items:center"><input type="hidden" name="_csrf" value="<?=h(csrf_token('student-area'))?>"><input type="hidden" name="action" value="assign_submission_cohort"><input type="hidden" name="submission_id" value="<?=(int)$submission['id']?>"><select name="cohort_id"><?php foreach($cohorts as $cohort):?><option value="<?=(int)$cohort['id']?>"<?=(int)($submission['cohort_id']??0)===(int)$cohort['id']?' selected':''?>><?=h((string)$cohort['title'])?></option><?php endforeach;?></select><button type="submit">Salvar</button></form></div></article><?php endforeach;?></div><?php endif;?></section>
<?php admin_shell_end();
